<?php use App\Core\Helpers as H;use App\Services\PromoGraphicService;$canManage=H::canAdmin('promotions.manage');?>
<div class="page-heading"><div><h1>Promotional Graphics</h1><p class="muted">Manage the public library. Archived graphics are retained safely but no longer available publicly.</p></div><?php if($canManage):?><a class="btn" href="/admin/promo-library/new">Upload graphics</a><?php endif;?></div>
<?php if(!$graphics):?><div class="card"><p>No promotional graphics have been uploaded.</p></div><?php else:?><div class="promo-admin-grid">
<?php foreach($graphics as $graphic):?><article class="card promo-admin-card"><img src="/admin/promo-library/<?=(int)$graphic['id']?>/image" alt="<?=H::e($graphic['alt_text'])?>"><div><strong><?=H::e(PromoGraphicService::PLATFORMS[$graphic['platform']]??$graphic['platform'])?></strong><p><?=H::e($graphic['size_label'])?> · <?=H::e($graphic['category'])?></p><p>Status: <?=$graphic['is_active']?'Active':'Inactive'?></p><?php if($canManage):?><div class="promo-actions"><a class="btn" href="/admin/promo-library/<?=(int)$graphic['id']?>">Edit</a><form method="post" action="/admin/promo-library/<?=(int)$graphic['id']?>/archive" onsubmit="return confirm('Archive this graphic? It will immediately leave the public library.');"><input type="hidden" name="_csrf" value="<?=H::csrf()?>"><button class="danger">Archive</button></form></div><?php endif;?></div></article><?php endforeach;?></div><?php endif;?>
